CREATE OR REPLACE FUNCTION public.guard_vip_credit_review() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN IF TG_OP='INSERT' AND (NEW.vip_credit_status <> 'pending' OR NEW.vip_credit_review_note IS NOT NULL) THEN RAISE EXCEPTION 'Credit decisions require staff review'; END IF; IF TG_OP='UPDATE' AND (NEW.vip_credit_status IS DISTINCT FROM OLD.vip_credit_status OR NEW.vip_credit_review_note IS DISTINCT FROM OLD.vip_credit_review_note) THEN RAISE EXCEPTION 'Credit decisions require privileged review'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_vip_credit_review BEFORE INSERT OR UPDATE ON public.support_tickets FOR EACH ROW EXECUTE FUNCTION public.guard_vip_credit_review();